"""Generated byte-level probes against the actual private Go loader."""
import base64
import gzip
import io
import json
import os
import subprocess
import tarfile
from pathlib import Path

ROOT = Path(__file__).resolve().parents[2]


def header(name="file.json", kind=b"0", size=0):
    h = tarfile.TarInfo("placeholder")
    h.type, h.size, h.mode = kind, size, 0o644
    raw = bytearray(h.tobuf(format=tarfile.USTAR_FORMAT))
    raw[:100] = name.encode().ljust(100, b"\0")
    return checksum(raw)


def checksum(raw):
    raw = bytearray(raw)
    raw[148:156] = b" " * 8
    raw[148:156] = ("%06o\0 " % sum(raw)).encode()
    return bytes(raw)


def pax(values):
    data = b""
    for key, value in values:
        body = key.encode() + b"=" + value.encode() + b"\n"
        n = len(body) + 2
        while n != len(str(n)) + 1 + len(body):
            n = len(str(n)) + 1 + len(body)
        data += str(n).encode() + b" " + body
    return header("pax", b"x", len(data)) + data + b"\0" * (-len(data) % 512)


def snapshot(content):
    return [dict(Path=e.path, Type=e.kind, Mode=e.mode, UID=e.uid, GID=e.gid,
                 Size=e.size, Digest=e.digest, LinkTarget=e.link_target,
                 Data=None if e.data is None else base64.b64encode(e.data).decode())
            for e in sorted(content.entries.values(), key=lambda e: e.path)]


def test_go_archive_differential(tmp_path):
    from agent_suite._archive import load_layer
    probes = []

    def add(name, raw):
        probes.append(dict(name=name, gzip=base64.b64encode(gzip.compress(raw, mtime=0)).decode()))

    zero = b"\0" * 1024
    for field, width in [(100, 8), (108, 8), (116, 8), (124, 12), (136, 12), (329, 8), (337, 8)]:
        values = [b"\0" * width, b" " * width, b"+0".ljust(width, b"\0"),
                  b"-0".ljust(width, b"\0"), b"08".ljust(width, b"\0"),
                  b"0\0invalid"[:width].ljust(width, b"\0")]
        for number in [-(1 << 63), -1, 0, 1, 1 << 63]:
            raw = (number & ((1 << (8 * width - 1)) - 1)) | (1 << (8 * width - 1))
            values.append(raw.to_bytes(width, "big"))
        for value in values:
            raw = bytearray(header())
            raw[field:field + width] = value
            add(f"numeric-{field}-{value.hex()}", checksum(raw) + zero)
    for key in ["mtime", "atime", "ctime", "uid", "gid", "size"]:
        for value in ["", "0", "+0", "-0", "00", "0.", "0.0000000001", "1e0", "-1", "-62135596800", str(1 << 63), "0" * 5001]:
            add(f"pax-{key}-{value}", pax([(key, value)]) + header() + zero)
    for name in ["dir/", "dir//", "file.json", "../escape", "a/../b", "a//b"]:
        for kind in [b"0", b"\0", b"5", b"1", b"2"]:
            add(f"effective-{kind.hex()}-{name}", pax([("path", name)]) + header(kind=kind) + zero)
    for name in ["file.json", "file.bin"]:
        for physical in [0, 1, 2]:
            for logical in [0, 1, 3]:
                for offset, length in [(0, 0), (0, 1), (1, 1), (-1, 0), (3, 0)]:
                    values = [("GNU.sparse.map", f"{offset},{length}"), ("GNU.sparse.numblocks", "1"),
                              ("GNU.sparse.size", str(logical))]
                    body = bytes(physical) + b"\0" * (-physical % 512)
                    add(f"sparse-{name}-{physical}-{logical}-{offset}-{length}",
                        pax(values) + header(name, size=physical) + body + zero)
    for key in ["GNU.sparse.size", "GNU.sparse.numblocks"]:
        values = [("GNU.sparse.map", ""), ("GNU.sparse.major", "0"), ("GNU.sparse.minor", "1"),
                  ("GNU.sparse.numblocks", "0"), ("GNU.sparse.size", "0"), (key, "0" * 5001)]
        add("zero-padded-" + key, pax(values) + header() + zero)
    for token_size in [8192, 1 << 20]:
        body = b"0" * (token_size - 1) + b"\n"
        values = [("GNU.sparse.major", "1"), ("GNU.sparse.minor", "0"),
                  ("GNU.sparse.realsize", "0")]
        add(f"sparse-long-count-{token_size}", pax(values) + header(size=len(body)) + body + zero)
    unused = bytearray(header())
    unused[157:170] = b"ignored-value"
    add("unused-regular-linkname", checksum(unused) + zero)
    corpus = json.loads((ROOT / "testdata/conformance/archive-cases.json").read_bytes())
    for case in corpus["cases"][:50]:
        raw = gzip.decompress(base64.b64decode(case["gzip"]))
        for length in [0, 1, 10, 511, 512, len(raw) - 1]:
            if 0 <= length < len(raw):
                add(f"truncate-{case['name']}-{length}", raw[:length])
    requests = tmp_path / "requests.json"
    requests.write_text(json.dumps(probes), encoding="utf-8")
    executable = tmp_path / ("oracle.exe" if os.name == "nt" else "oracle")
    subprocess.run(["go", "test", "-c", "-o", str(executable), "./internal/artifact"], cwd=ROOT, check=True)
    subprocess.run([str(executable), "-test.run=^TestSharedArchiveCases$"], cwd=ROOT, check=True,
                   env={**os.environ, "AGENTSUITE_ARCHIVE_ORACLE": str(requests)}, capture_output=True)
    expected = json.loads(Path(str(requests) + ".result").read_bytes())
    mismatches = []
    for case in expected:
        try:
            result = snapshot(load_layer(io.BytesIO(base64.b64decode(case["gzip"]))))
        except ValueError:
            result = None
        if (result is not None) != case["valid"] or case["valid"] and result != case["entries"]:
            mismatches.append((case["name"], case.get("error"), result, case["entries"]))
    assert not mismatches, mismatches[:10]
    assert len(expected) >= 400
